'''MUST USE CONDA ENVIRONMENT sandhills_lst_env'''from pathlib import Pathfrom collections import defaultdictfrom pyhdf.SD import SD, SDCfrom rasterio.crs import CRSfrom PreprocessData import parse_filenamefrom PreprocessData import compute_monthly_meanfrom PreprocessData import trim_filesfrom PreprocessData import reproject_datafrom PreprocessData import read_lst_hdffrom PreprocessData import cloud_cover_maskfrom PreprocessData import convert_lst' GLOBAL CONSTANTS 'STUDY_BOUNDS = {    "west":-91.252441,"east": -70.345459,    "south": 30.439202,"north": 38.401949,}DATA_ROOT = Path("./data")OUTPUT_DIR = Path("./data/processed")OUTPUT_CRS = CRS.from_epsg(32617)# fixed tile extent - found this online i hope it worksTILE_XMIN = -7783653.638TILE_XMAX = -6671703.118TILE_YMIN =  3335851.559TILE_YMAX =  4447802.078TILE_ROWS  = 1200TILE_COLS  = 1200OUTPUT_CRS = CRS.from_epsg(32617)#sinusoidal CRS - found this online i hope it worksMODIS_SIN_CRS = CRS.from_proj4("+proj=sinu +lon_0=0 +x_0=0 +y_0=0 "    "+a=6371007.181 +b=6371007.181 +units=m +no_defs")# Get file pathshdf_files = sorted(DATA_ROOT.rglob("*.hdf")) # Get all hdf files only# split lst & ndvi files into separate listslst_files = []ndvi_files = []for f in hdf_files:    if f.name.startswith(("MOD11A1", "MYD11A1")):        lst_files.append(f)    else:        ndvi_files.append(f)        #Set up storage variablesmonthly_day = defaultdict(list)monthly_night = defaultdict(list)saved_transform = Nonesaved_crs = None# Iterate through filesfor i, hdf_path in enumerate(lst_files):    try:        # get file & read it        satellite, date = parse_filename(hdf_path)        lst_day, lst_night, qc_day, qc_night, clear_day, clear_night = read_lst_hdf(hdf_path)                # apply cloud cover & quality masks        lst_day = cloud_cover_mask(lst_day, qc_day, clear_day)        lst_night = cloud_cover_mask(lst_night, qc_night, clear_night)                # Put into celsius        lst_day = convert_lst(lst_day)        lst_night = convert_lst(lst_night)        # Reproject         lst_day, transform = reproject_data(lst_day)        lst_night, _ = reproject_data(lst_night) # dont need to overwrite transform                # trim        lst_day, clip_transform = trim_files(lst_day, transform, OUTPUT_CRS)        lst_night, _ = trim_files(lst_night, transform, OUTPUT_CRS)                # build monthly lists        monthly_day[(date.year, date.month)].append(lst_day)        monthly_night[(date.year, date.month)].append(lst_night)                saved_transform = clip_transform        saved_crs = OUTPUT_CRS            except Exception as e:        print(f"Error Occured - Skipping {hdf_path.name} -- {e}")                # Calculate monthly averages & savecompute_monthly_mean(monthly_day, monthly_night, OUTPUT_DIR, saved_transform, saved_crs)